insert into public.characters (id, name, description, personality, traits, relationships, history, casting_status, sort_order) values ('a7b414fa-b6e9-5916-a989-6132fff46c7c', 'Жора', 'Обычный новокузнецкий парень, попавший не в то место и не в то время. Вынужден бороться с Доном криминальными методами.', 'Характер уточним по полному разбору.', 'Борется с Доном криминальными методами.', 'Противник Дона Потника. Карпуха — член банды Жоры.', 'Сведения из прежнего разбора. Конфликт связан с пропавшей партией кокаина и долгом в миллион долларов.', 'uncertain', 1) on conflict (id) do update set name=excluded.name, description=excluded.description, personality=excluded.personality, traits=excluded.traits, relationships=excluded.relationships, history=excluded.history, casting_status=excluded.casting_status, sort_order=excluded.sort_order;
insert into public.characters (id, name, description, personality, traits, relationships, history, casting_status, sort_order) values ('c4017715-0437-529c-a99a-6aa571d12ab1', 'Дон Потник', 'Унаследовал преступную империю. Его конфликт с Жорой — одна из центральных линий.', 'Характер уточним по полному разбору.', 'Стоит во главе собственной группировки.', 'Противостоит Жоре. Туз — его правая рука. Фёдор и Дима Черен — члены его банды.', 'В прежнем разборе отмечены похищения, убийства и перестрелка в ходе конфликта.', 'uncertain', 2) on conflict (id) do update set name=excluded.name, description=excluded.description, personality=excluded.personality, traits=excluded.traits, relationships=excluded.relationships, history=excluded.history, casting_status=excluded.casting_status, sort_order=excluded.sort_order;
insert into public.characters (id, name, description, personality, traits, relationships, history, casting_status, sort_order) values ('81b67d78-39e8-584e-a891-6b018eea6309', 'Туз', 'Правая рука Дона Потника.', 'Подробное описание пока не перенесено.', 'Близкий участник команды Дона.', 'Связан с Доном Потником.', 'Данные из доступного контекста прежнего разбора.', 'uncertain', 4) on conflict (id) do update set name=excluded.name, description=excluded.description, personality=excluded.personality, traits=excluded.traits, relationships=excluded.relationships, history=excluded.history, casting_status=excluded.casting_status, sort_order=excluded.sort_order;
insert into public.characters (id, name, description, personality, traits, relationships, history, casting_status, sort_order) values ('a211dbea-b7db-5c72-9857-7955e17a8a31', 'Святослав', 'Его роль связана с пленением и подозрением в предательстве.', 'Не определён в доступном кратком разборе.', 'Его роль и связь с информатором остаются нераскрытыми.', 'Связи нужно уточнить по полному разбору.', 'Пленение Святослава — одна из отмеченных линий. Не делаем вывод о предательстве без подтверждения.', 'uncertain', 5) on conflict (id) do update set name=excluded.name, description=excluded.description, personality=excluded.personality, traits=excluded.traits, relationships=excluded.relationships, history=excluded.history, casting_status=excluded.casting_status, sort_order=excluded.sort_order;
insert into public.characters (id, name, description, personality, traits, relationships, history, casting_status, sort_order) values ('e40cbe4a-1c29-5f73-a46c-ab50d9f62a3b', 'Паша', 'В прежнем разборе отмечена его гибель.', 'Подробности нужно дополнить.', 'Возвращение в финальном фильме требует сюжетного решения.', 'Подробности нужно дополнить.', 'Гибель отмечена в доступном контексте. Обстоятельства уточним по полному разбору.', 'uncertain', 6) on conflict (id) do update set name=excluded.name, description=excluded.description, personality=excluded.personality, traits=excluded.traits, relationships=excluded.relationships, history=excluded.history, casting_status=excluded.casting_status, sort_order=excluded.sort_order;
insert into public.characters (id, name, description, personality, traits, relationships, history, casting_status, sort_order) values ('833ee109-060c-5764-a8ec-3fc57e510c48', 'Ваня', 'В прежнем разборе характеризуется как надёжный участник.', 'Надёжность — отмеченная черта; остальное нужно уточнить.', 'Подробности нужно дополнить.', 'Подробности нужно дополнить.', 'Данные из доступного контекста прежнего разбора.', 'uncertain', 7) on conflict (id) do update set name=excluded.name, description=excluded.description, personality=excluded.personality, traits=excluded.traits, relationships=excluded.relationships, history=excluded.history, casting_status=excluded.casting_status, sort_order=excluded.sort_order;
insert into public.characters (id, name, description, personality, traits, relationships, history, casting_status, sort_order) values ('fb2a036f-ea7a-52c8-a90c-087fd1df1131', 'Химик', 'Персонаж, связанный с наркотиками.', 'Подробности нужно дополнить.', 'Связь с наркотиками отмечена в прежнем разборе.', 'Подробности нужно дополнить.', 'Роль в финальном фильме пока не определена.', 'uncertain', 8) on conflict (id) do update set name=excluded.name, description=excluded.description, personality=excluded.personality, traits=excluded.traits, relationships=excluded.relationships, history=excluded.history, casting_status=excluded.casting_status, sort_order=excluded.sort_order;
insert into public.characters (id, name, description, personality, traits, relationships, history, casting_status, sort_order) values ('5a918ad2-11c9-58c3-87c5-beb50ece6cb4', 'Джорданио Быхулиос', 'Загадочный персонаж.', 'В доступном контексте нет подробностей.', 'Связан с отдельной группировкой.', 'Серёга Авиаторы — его правая рука. Неясно, на чьей стороне Джорданио.', 'Внезапно появляется в конце второй серии. Возможно, играет в свою игру.', 'uncertain', 3) on conflict (id) do update set name=excluded.name, description=excluded.description, personality=excluded.personality, traits=excluded.traits, relationships=excluded.relationships, history=excluded.history, casting_status=excluded.casting_status, sort_order=excluded.sort_order;
