insert into public.characters (id, name, description, personality, traits, relationships, history, casting_status, sort_order) values ('b4f6edf8-c6d0-52d5-9d63-04571f098fd2', 'Серёга Авиаторы', 'Правая рука Джорданио Быхулиоса.', 'Характер пока не описан.', '', 'Правая рука Джорданио Быхулиоса.', '', 'uncertain', 12) on conflict (id) do update set name=excluded.name, description=excluded.description, personality=excluded.personality, traits=excluded.traits, relationships=excluded.relationships, history=excluded.history, casting_status=excluded.casting_status, sort_order=excluded.sort_order;
insert into public.lore_chapters (id, title, sort_order, content) values ('ba316eab-8388-5ca5-9852-7d181d091be8', 'Основной конфликт', 1, 'Жора и Дон Потник противостоят друг другу из-за пропавшей партии кокаина и долга в миллион долларов.
insert into public.lore_chapters (id, title, sort_order, content) values ('06af110a-37b7-51d4-8910-f1ab5ca5d399', 'Герои и группировки', 2, 'Дон Потник унаследовал преступную империю. Жора, обычный новокузнецкий парень, попавший не в то место и не в то время, вынужден бороться с Доном криминальными методами.
insert into public.lore_chapters (id, title, sort_order, content) values ('8544d70b-4f54-5845-80fa-26e4d1a28358', 'Что осталось открытым', 3, 'Непонятно, на чьей стороне Джорданио — или он вовсе играет в свою игру.') on conflict (id) do update set title=excluded.title, sort_order=excluded.sort_order, content=excluded.content;
